namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings > 0 ? (double)RatingSum / TotalRatings : 0;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;
    private readonly Lock _lock = new();

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple and delicious pizza with fresh mozzarella, tomatoes, and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps =
                [
                    "Preheat oven to 475°F (245°C) with a pizza stone.",
                    "Stretch dough into a 12-inch circle.",
                    "Spread crushed tomatoes over dough, leaving a 1-inch border.",
                    "Tear mozzarella and distribute evenly.",
                    "Bake for 10-12 minutes until crust is golden.",
                    "Top with fresh basil and a drizzle of olive oil."
                ],
                TotalRatings = 12, RatingSum = 52
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta made with eggs, pecorino, guanciale, and black pepper.",
                Ingredients = ["Spaghetti", "Guanciale (or pancetta)", "Eggs", "Pecorino Romano", "Black pepper", "Salt"],
                Steps =
                [
                    "Cook spaghetti in salted water until al dente.",
                    "Cut guanciale into small strips and cook until crispy.",
                    "Whisk eggs with grated pecorino and black pepper.",
                    "Drain pasta, reserving 1 cup of pasta water.",
                    "Toss hot pasta with guanciale off heat.",
                    "Add egg mixture, tossing quickly. Add pasta water to reach creamy consistency."
                ],
                TotalRatings = 8, RatingSum = 38
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Cumin", "Turmeric"],
                Steps =
                [
                    "Marinate chicken in yogurt and spices for at least 1 hour.",
                    "Grill or broil chicken until charred.",
                    "Sauté onion, garlic, and ginger until soft.",
                    "Add tomato sauce and spices, simmer 15 minutes.",
                    "Add cream and cut chicken pieces.",
                    "Simmer together for 10 minutes. Serve with rice or naan."
                ],
                TotalRatings = 15, RatingSum = 70
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Biryani", Category = "Indian",
                Description = "Fragrant layered rice dish with mixed vegetables and aromatic spices.",
                Ingredients = ["Basmati rice", "Mixed vegetables", "Onions", "Yogurt", "Saffron", "Whole spices (cardamom, cinnamon, bay leaf)", "Mint", "Cilantro", "Ghee"],
                Steps =
                [
                    "Soak basmati rice for 30 minutes, then parboil.",
                    "Fry sliced onions until golden brown.",
                    "Cook vegetables with spices and yogurt.",
                    "Layer rice and vegetable mixture in a heavy pot.",
                    "Add saffron milk, mint, and cilantro between layers.",
                    "Seal pot and cook on low heat for 25 minutes."
                ],
                TotalRatings = 6, RatingSum = 27
            },
            new Recipe
            {
                Id = 5, Title = "Tacos al Pastor", Category = "Mexican",
                Description = "Marinated pork tacos with pineapple, cilantro, and onion.",
                Ingredients = ["Pork shoulder", "Dried chiles", "Pineapple", "Corn tortillas", "Onion", "Cilantro", "Lime", "Achiote paste"],
                Steps =
                [
                    "Blend dried chiles, achiote, and pineapple juice into a marinade.",
                    "Marinate sliced pork for at least 4 hours.",
                    "Cook pork on high heat until charred.",
                    "Grill pineapple slices until caramelized.",
                    "Warm tortillas on a dry skillet.",
                    "Assemble tacos with pork, pineapple, onion, cilantro, and lime."
                ],
                TotalRatings = 10, RatingSum = 47
            },
            new Recipe
            {
                Id = 6, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh avocado dip with lime, cilantro, and jalapeño.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
                Steps =
                [
                    "Halve and pit avocados, scoop into a bowl.",
                    "Mash with a fork to desired consistency.",
                    "Add lime juice and salt.",
                    "Fold in diced onion, tomato, jalapeño, and cilantro.",
                    "Taste and adjust seasoning. Serve immediately with chips."
                ],
                TotalRatings = 20, RatingSum = 90
            },
            new Recipe
            {
                Id = 7, Title = "Beef Stir-Fry with Broccoli", Category = "Asian",
                Description = "Quick and savory beef and broccoli in a ginger-soy sauce.",
                Ingredients = ["Flank steak", "Broccoli", "Soy sauce", "Oyster sauce", "Garlic", "Ginger", "Cornstarch", "Sesame oil", "Rice"],
                Steps =
                [
                    "Slice steak thinly against the grain and marinate in soy sauce and cornstarch.",
                    "Blanch broccoli florets for 2 minutes.",
                    "Heat wok over high heat with oil.",
                    "Stir-fry beef until browned, remove.",
                    "Stir-fry garlic and ginger, add broccoli.",
                    "Return beef, add sauce, and toss until glazed. Serve over rice."
                ],
                TotalRatings = 9, RatingSum = 40
            },
            new Recipe
            {
                Id = 8, Title = "Pad Thai", Category = "Asian",
                Description = "Classic Thai stir-fried noodles with shrimp, peanuts, and tamarind sauce.",
                Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Sugar", "Lime"],
                Steps =
                [
                    "Soak rice noodles in warm water for 30 minutes.",
                    "Mix tamarind paste, fish sauce, and sugar for the sauce.",
                    "Stir-fry shrimp until pink, push to side, scramble eggs.",
                    "Add drained noodles and sauce, toss to coat.",
                    "Add bean sprouts and green onions.",
                    "Serve with crushed peanuts and lime wedges."
                ],
                TotalRatings = 14, RatingSum = 63
            },
        ];
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is not null && stars is >= 1 and <= 5)
            {
                recipe.TotalRatings++;
                recipe.RatingSum += stars;
            }
        }
    }

    public Recipe AddRecipe(string title, string category, string description, List<string> ingredients, List<string> steps)
    {
        lock (_lock)
        {
            var recipe = new Recipe
            {
                Id = _nextId++,
                Title = title,
                Category = category,
                Description = description,
                Ingredients = ingredients,
                Steps = steps
            };
            _recipes.Add(recipe);
            return recipe;
        }
    }
}

